use std::env;

fn main() {
    let mut inputs: Vec<String> = env::args().skip(1).collect();

    if inputs.is_empty() {
        inputs = vec![
            "one".to_string(),
            "two.three".to_string(),
            "four.five.six".to_string(),
        ];
    }

    for input in &inputs {
        print!("{} ", idna::to_ascii(input));
        print!("{} ", idna::to_unicode(input));
        print!("{} ", idna::punycode_encode(input));
        print!("{} ", idna::punycode_decode(input));
        print!("{} ", if idna::is_valid_domain(input) { 1 } else { 0 });
        print!("{} ", if idna::is_valid_label(input) { 1 } else { 0 });
        print!("{} ", if idna::is_ascii_domain(input) { 1 } else { 0 });
        print!("{} ", if idna::is_idn_domain(input) { 1 } else { 0 });
        print!("{} ", idna::to_lower(input));
        print!("{} ", idna::normalize(input));
        println!("{}", idna::count_labels(input));
    }
}

