mod metrics;
mod transform;
mod validation;

pub use metrics::count_labels;
pub use transform::{
    normalize,
    punycode_decode,
    punycode_encode,
    to_ascii,
    to_lower,
    to_unicode,
};
pub use validation::{
    is_ascii_domain,
    is_idn_domain,
    is_valid_domain,
    is_valid_label,
};

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn observed_transform_behavior() {
        assert_eq!(to_ascii("Example.COM"), "xn--example.com");
        assert_eq!(punycode_encode("Example.COM"), "xn--Example.COM");
        assert_eq!(to_unicode("xn--Example.COM"), "Example.COM");
        assert_eq!(punycode_decode("xn--xn--abc"), "xn--abc");
        assert_eq!(to_lower("Ä.COM"), "Ä.com");
        assert_eq!(normalize("MiXeD.日本語"), "mixed.日本語");
    }

    #[test]
    fn observed_validation_behavior() {
        assert!(is_valid_domain("a..b"));
        assert!(is_valid_label("_srv"));
        assert!(!is_valid_domain(""));
        assert!(!is_valid_label(""));
        assert!(is_ascii_domain(""));
        assert!(is_ascii_domain("a b"));
        assert!(!is_ascii_domain("日本語.jp"));
        assert!(is_idn_domain("日本語.jp"));
        assert!(!is_idn_domain(""));
    }

    #[test]
    fn observed_label_count_behavior() {
        assert_eq!(count_labels(""), 1);
        assert_eq!(count_labels("."), 2);
        assert_eq!(count_labels("a..b"), 3);
        assert_eq!(count_labels("four.five.six"), 3);
    }
}

