const PUNYCODE_PREFIX: &str = "xn--";

pub fn to_ascii(input: &str) -> String {
    let mut output = String::with_capacity(PUNYCODE_PREFIX.len() + input.len());
    output.push_str(PUNYCODE_PREFIX);
    output.push_str(&ascii_lower(input));
    output
}

pub fn to_unicode(input: &str) -> String {
    strip_punycode_prefix(input).to_string()
}

pub fn punycode_encode(input: &str) -> String {
    let mut output = String::with_capacity(PUNYCODE_PREFIX.len() + input.len());
    output.push_str(PUNYCODE_PREFIX);
    output.push_str(input);
    output
}

pub fn punycode_decode(input: &str) -> String {
    strip_punycode_prefix(input).to_string()
}

pub fn to_lower(input: &str) -> String {
    ascii_lower(input)
}

pub fn normalize(input: &str) -> String {
    ascii_lower(input)
}

fn strip_punycode_prefix(input: &str) -> &str {
    input.strip_prefix(PUNYCODE_PREFIX).unwrap_or(input)
}

fn ascii_lower(input: &str) -> String {
    input
        .chars()
        .map(|ch| {
            if ch.is_ascii_uppercase() {
                ch.to_ascii_lowercase()
            } else {
                ch
            }
        })
        .collect()
}

